"""Dependency-free, deterministic GitHub Pages site generator."""
import csv, html, io, json, re, shutil, sys
from collections import Counter
from pathlib import Path
from prepare_data import prepare
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'site'
D=prepare()
(ROOT/'data/ledger.json').write_text(json.dumps(D,indent=2,ensure_ascii=False)+'\n')
ROWS=D['rows']; SOURCES=D['sources']; CATS={c['id']:c['name'] for c in D['categories']}
COUNTS=Counter(r['category'] for r in ROWS)
BAD={'https://www.skillz.com/terms-of-service/'}
UPSTREAM='https://github.com/karagemop466-tech/FreeMoneyApps/blob/'+D['upstreamCommit']+'/assets/data.js'
E=lambda v:html.escape(str(v),quote=True)
ICONS={'tech':'⌘','forecasting':'◎','creative':'✎','sports':'⚑','market':'↗','trivia':'?','skill':'♜','directory':'▤','pools':'⊞'}
LABELS={'entry':'Entry route','prize':'Cash prize','deadline':'Deadline','eligibility':'Eligibility','ai':'AI & automation','payout':'Payment & claiming','requirements':'Submission requirements'}
def a(url,text,**kw):
    if not re.match(r'^(https://|\.?\.?/|[a-zA-Z0-9])',url) or url.startswith(('javascript:', 'data:')):raise ValueError(url)
    extra=' target="_blank" rel="noopener noreferrer"' if url.startswith('https://') else ''
    return f'<a href="{E(url)}"{extra}'+''.join(f' {k}="{E(v)}"' for k,v in kw.items())+f'>{text}</a>'
def source_link(id,prefix,text='↗',cls='evidence-link'):
    return a(SOURCES[id]['url'],E(text),**{'class':cls,'title':SOURCES[id]['title']+' · checked 1 Nov 2026'})
def refs(field,prefix):
    return ''.join(source_link(s,prefix,'['+str(i+1)+']') for i,s in enumerate(field['sources']))
def nav(prefix,current):
    def link(path,text,icon,count=None):
        return f'<a href="{prefix+path}"'+(' aria-current="page"' if current==path else '')+f'><span class="nav-icon" aria-hidden="true">{icon}</span>{text}'+(f'<span class="nav-count">{count}</span>' if count is not None else '')+'</a>'
    main=link('index.html','Overview','⊞')+link('competitions.html','All competitions','▤',len(ROWS))+link('saved.html','Saved opportunities','☆')
    categories=''.join(link('categories/'+k+'.html',E(v.replace(' competitions','').replace(' tournaments','').replace('Free pool & league platforms','Pool & league tools').replace('Fantasy & sports picks','Sports & fantasy').replace('Directories & forums','Directories').replace('Tech & data','Tech & data')),ICONS[k],COUNTS[k]) for k,v in CATS.items())
    research=link('summary.html','Executive summary','▧')+link('review.html','Flagged for Review','⚐',sum(bool(r['flags']) for r in ROWS))+link('methodology.html','Verification method','✓')+link('sources.html','Source notebook','↗')
    return f'''<aside class="sidebar" id="sidebar"><a class="brand" href="{prefix}index.html"><img src="{prefix}assets/icon.svg" width="38" height="38" alt=""><span>Prize Ledger<small>Free entry. Real opportunity.</small></span></a><p class="nav-label">Workspace</p><nav aria-label="Workspace">{main}</nav><p class="nav-label">Explore categories</p><nav aria-label="Categories">{categories}</nav><p class="nav-label">Research desk</p><nav aria-label="Research">{research}</nav><div class="sidebar-bottom"><div class="source-badge"><span class="dot"></span>Evidence over assumptions</div><p>Independent research. No sponsors.<br>Unknown values stay blank.<br>Snapshot · 1 November 2026</p><a class="small-link" href="https://github.com/sassnarep3-star/Own2">View on GitHub ↗</a></div></aside>'''
def page(path,title,content,crumb='Workspace',desc='A source-linked research dashboard for free-to-enter cash prize competitions.'):
    prefix='../' if '/' in path else './'
    shell=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{E(desc)}"><meta name="theme-color" content="#165b45"><title>{E(title)} · Prize Ledger</title><link rel="icon" href="{prefix}assets/icon.svg"><link rel="stylesheet" href="{prefix}assets/style.css"><script defer src="{prefix}assets/app.js"></script></head><body data-page="{E(path)}"><a class="skip" href="#main">Skip to content</a>{nav(prefix,path)}<div class="workspace"><header class="topbar"><button class="menu" aria-controls="sidebar" aria-expanded="false" id="menu">☰ <span class="sr-only">Toggle navigation</span></button><span class="crumb">{E(crumb)} <span aria-hidden="true">/</span> <strong>{E(title)}</strong></span><div class="right"><span class="date-pill">◷ &nbsp; Research snapshot · 01 Nov 2026</span><a href="{prefix}methodology.html">How we verify ↗</a></div></header><main id="main">{content}<footer class="footer"><span>© 2026 Prize Ledger · An independent competition research desk.</span><span>Prizes are not guaranteed. {a(prefix+'methodology.html','Official rules always take precedence.')} &nbsp; {a(prefix+'data/ledger.csv','Download data ↓')}</span></footer></main></div></body></html>'''
    dest=OUT/path;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(shell)
def heading(eyebrow,title,desc,button='',prefix='./'):
    return f'<p class="eyebrow">{eyebrow}</p><div class="page-heading"><div><h1>{title}</h1><p class="lede">{desc}</p></div>{button}</div>'
def metrics():
    vals=[('Opportunities cataloged',len(ROWS),'All 206 original listings retained','▤',''),('Free + cash award confirmed',sum(r['freeCash'] for r in ROWS),'Entry & cash amount sourced; other checks apply','✓','green'),('Official pages inspected',len(SOURCES),'Field-level evidence, not blanket verification','↗','green'),('Categories to explore',len(CATS),'From coding challenges to creative awards','⊞','')]
    return '<section class="stats" aria-label="Research coverage">'+''.join(f'<div class="stat"><div class="stat-top">{t}<span class="stat-icon" aria-hidden="true">{ic}</span></div><strong>{n}</strong><small class="{cl}">{s}</small></div>' for t,n,s,ic,cl in vals)+'</section>'
def notice(prefix='./'):
    return f'<div class="notice"><span aria-hidden="true">ⓘ</span><div><strong>Source-checked, not assumption-filled.</strong> Blank cells mean unverified. {len(ROWS)-sum(r["checked"] for r in ROWS)} listings remain discovery leads; not every row is a free cash contest. {a(prefix+"review.html","See the review queue →")}</div></div>'
def shortlist(prefix='./'):
    picks=[('paypal-ai-2026','A practical build with an explicitly required PayPal + AI integration.','$12,000','first place','Free + cash award','12 Nov · Pacific Time'),('futureeval-fall-2026','A dedicated bot tournament. Build and evaluate a forecasting agent.','$50,000','advertised pool','Cash equivalents possible','6 Jan 2027'),('nfl-big-data-bowl-2027','A focused analytics project with conditional permission for external models.','$100,000','total pool','Free + cash award','6 Jan · 23:59 UTC')]
    cards=[]
    for id,why,amount,kind,badge,date in picks:
        r=next(x for x in ROWS if x['id']==id)
        cards.append(f'''<article class="pick"><div class="pick-top"><span class="category-mark" aria-hidden="true">{ICONS[r['category']]}</span><span class="badge {'amber' if id.startswith('future') else ''}">{badge}</span></div><h3>{E(r['name'])}</h3><p>{why}</p><div class="pick-prize">{amount}<small>{kind}</small></div><div class="pick-meta"><span>◷ &nbsp; {date}</span>{a(prefix+'competitions.html?entry='+id,'View evidence →')}</div></article>''')
    return '<section aria-labelledby="picks-title"><div class="section-head"><div><h2 id="picks-title">Worth a closer look</h2><p>Editorial research priorities for AI-assisted work. Not earnings predictions.</p></div>'+a(prefix+'summary.html','Read the analysis →')+'</div><div class="picks">'+''.join(cards)+'</div></section>'
def field_cell(r,key,prefix):
    field=r['fields'][key]
    if not field:return '<td class="blank" data-label="'+LABELS[key]+'" aria-label="'+LABELS[key]+': unverified; intentionally blank"></td>'
    value=field['value'];classes='money' if key=='prize' else ''
    # Avoid truncating source-confirmed claims; complete conditions remain visible.
    if key=='entry':
        label='Free entry' if value.startswith('Free;') or value.startswith('Free to') else 'Mixed / restricted'
        return f'<td data-label="Entry"><span class="badge {"" if label=="Free entry" else "amber"}">{label}</span><span class="field-note">{E(value)}</span>{refs(field,prefix)}</td>'
    return f'<td data-label="{LABELS[key]}"><span class="{classes}">{E(value)}</span>{refs(field,prefix)}</td>'
def render_row(r,prefix):
    fields=r['fields']; source=r.get('checkedSource'); ischecked=r['checked']
    url=SOURCES[source]['url'] if source else r.get('listedOperator') or next(iter(r['candidates']),None)
    if url in BAD:url='https://www.skillz.com/'
    evidence=a(url,'Official source ↗' if source else 'Listed source ↗',**{'class':'source-link'}) if url else ''
    evidence+=f'<span class="source-state {"checked" if ischecked else ""}">{"Source inspected · 01 Nov" if ischecked else "Unverified link & claims"}</span>'
    evidence+=f'<span class="badge {"" if r["freeCash"] else "amber" if r["flags"] else "gray"}" style="margin-top:7px">{"Free + cash sourced" if r["freeCash"] else "Review required"}</span>'
    detail=''.join('<dt>'+LABELS[k]+'</dt><dd>'+ (E(v['value'])+refs(v,prefix) if v else '<span class="blank" aria-label="Unverified; intentionally blank"></span>')+'</dd>' for k,v in fields.items())
    detail+='<dt>Unverified fields</dt><dd>'+E(', '.join(r['missing']) or 'No empty tracked fields; specific cautions below still apply.')+'</dd>'
    flags='<ul>'+''.join('<li>'+E(f)+'</li>' for f in r['flags'])+'</ul>' if r['flags'] else ''
    origin=a(UPSTREAM,'Original ledger record ↗')+' · '+a(prefix+'research/upstream.json','Archived claims (unverified)') if r['origin']=='upstream' else 'Added from current official-source research.'
    detail+=f'<dt>Provenance</dt><dd>{origin}</dd>'
    # Only a source notebook inspection counts as checked. Raw inherited links remain labeled candidates.
    if r.get('candidates'):
        links=[a(u,E(u)) for u in r['candidates'] if u not in BAD]
        detail+='<dt>Inherited source candidates · not independently verified</dt><dd>'+ '<br>'.join(links)+'</dd>'
    search=' '.join([r['name'],CATS[r['category']]]+[x['value'] for x in fields.values() if x])
    date=fields['deadline'].get('date','') if fields['deadline'] else ''
    prize=fields['prize'].get('amount',0) if fields['prize'] else 0
    ai=bool(fields['ai'] and any(s in fields['ai']['value'] for s in ['Human AI assistance','Bot-only','AutoML permitted','Must integrate','Must build using Kiro']))
    return f'''<tr id="{r['id']}" data-id="{r['id']}" data-search="{E(search.lower())}" data-category="{r['category']}" data-free="{str(r['freeCash']).lower()}" data-checked="{str(ischecked).lower()}" data-ai="{str(ai).lower()}" data-date="{date}" data-prize="{prize}" data-review="{str(bool(r['flags'])).lower()}"><td data-label="Competition"><button class="save" aria-label="Save {E(r['name'])}" aria-pressed="false" data-save="{r['id']}" hidden>☆</button><div class="competition-head"><span class="row-icon" aria-hidden="true">{ICONS[r['category']]}</span><div><p class="row-name">{E(r['name'])}</p><span class="row-category">{E(CATS[r['category']])}</span></div></div><details class="row-details"><summary>Details &amp; verification</summary><dl>{detail}</dl>{flags}</details></td>{field_cell(r,'prize',prefix)}{field_cell(r,'entry',prefix)}{field_cell(r,'deadline',prefix)}{field_cell(r,'ai',prefix)}<td data-label="Evidence">{evidence}</td></tr>'''
def table(rows,prefix='./',mode='all',title='Competition explorer',category=None):
    options=''.join(f'<option value="{k}">{E(v)}</option>' for k,v in CATS.items())
    filters=f'''<div class="filters"><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">Search competitions</span><input id="search" type="search" placeholder="Search competitions, skills or requirements…" autocomplete="off"></label><label class="sr-only" for="category">Category</label><select id="category"><option value="">All categories</option>{options}</select><label class="sr-only" for="evidence-filter">Evidence filter</label><select id="evidence-filter"><option value="all">All evidence levels</option><option value="checked">Official source inspected</option><option value="ai">AI use supported, with conditions</option><option value="unverified">Unverified leads</option></select><label class="sr-only" for="sort">Sort competitions</label><select id="sort"><option value="research">Research priorities first</option><option value="name">Name A–Z</option><option value="deadline">Deadline: soonest first</option></select><button id="reset" class="button" type="button">Reset</button></div>'''
    tabdata=[('all','All opportunities',len(rows)),('free','Free + cash sourced',sum(r['freeCash'] for r in rows)),('saved','Saved',0)]
    tabs='<div class="tabs" role="group" aria-label="Competition view">'+''.join(f'<button class="tab" data-view="{id}" aria-pressed="{str((id=="saved" if mode=="saved" else id=="all")).lower()}">{text} <span data-count="{id}">{n}</span></button>' for id,text,n in tabdata)+'</div>'
    # Confirmed entries first; alphabetical leads thereafter. No invented ROI ranking.
    priorities={'paypal-ai-2026':0,'futureeval-fall-2026':1,'nfl-big-data-bowl-2027':2,'gemma-paper-2026':3,'metaculus-cup-fall-2026':4}
    rows=sorted(rows,key=lambda r:(priorities.get(r['id'],5 if r['freeCash'] else 6 if r['checked'] else 7),r['name'].lower()))
    return f'''<section class="table-panel" id="explorer" data-mode="{mode}" data-category-lock="{category or ''}"><div class="panel-header"><div><h2>{title}</h2><p>{len(rows)} records · blank cells are unverified · expand a row for eligibility and sources</p></div>{a(prefix+'data/ledger.csv','↓ &nbsp; Export CSV',**{'class':'button','download':'ledger.csv'})}</div><div class="interactive" hidden>{tabs}{filters}</div><noscript><p class="noscript">All records are visible below. Search, saved lists and pagination require JavaScript. Every source and detail works without it.</p></noscript><div class="table-wrap"><table><caption class="sr-only">{title}: official evidence where checked; unsupported values remain blank.</caption><thead><tr><th scope="col">Competition / opportunity</th><th scope="col">Cash prize</th><th scope="col">Entry</th><th scope="col">Deadline</th><th scope="col">AI &amp; automation</th><th scope="col">Source &amp; status</th></tr></thead><tbody>{''.join(render_row(r,prefix) for r in rows)}</tbody></table></div><div class="empty" id="empty" hidden><strong>No matching opportunities</strong><p>Try a different search or reset your filters.</p></div><div class="pagination" hidden><span id="result-count" role="status" aria-live="polite"></span><div class="pager-actions"><button id="prev">← Previous</button><span id="page-number" style="padding:6px"></span><button id="next">Next →</button></div></div></section>'''
def bottom(prefix='./'):
    return f'''<div class="bottom-grid"><section class="info-card"><h2>A better way to choose where to compete</h2><div class="steps"><div><span class="step-num">01 / CHECK</span><strong>Start with the rules</strong><p>Confirm free entry, actual cash, eligibility and deadline.</p></div><div><span class="step-num">02 / MATCH</span><strong>Check the AI policy</strong><p>Assistance, bots and generated submissions are not the same.</p></div><div><span class="step-num">03 / COMMIT</span><strong>Scope the work</strong><p>Test one reproducible baseline before spending more time.</p></div></div></section><section class="info-card"><h2>A cash headline is not a cash guarantee</h2><p>Bonus credit, equipment and cash equivalents are different from withdrawable money. Missing payment terms are flagged, not filled in.</p>{a(prefix+'review.html','Explore flagged findings →')}</section></div>'''
def audit_files():
    lines=['# Audit and executive summary · 2026-11-01','',f'Inventory: {len(ROWS)} rows; 206 original listings + 10 event-level research additions. All original records structurally audited. {len(SOURCES)} official pages inspected; this is not a complete official verification of all inherited claims.','',f'Upstream snapshot: [{D["upstreamCommit"]}]({UPSTREAM}). The raw upstream archive is evidence of provenance, NOT a verified source for contest values.','', '## Important findings','', '- A source-checked field is supported by listed official evidence; it does not certify an entire event or personal eligibility.','- Six records have a sourced free-entry path and cash award. Three additional Metaculus event rows advertise monetary pools but permit cash-equivalent substitution; these are excluded from the strict free + cash filter.','- Source totals may overlap (platform vs event; ARC headline vs tracks). No aggregate prize total or expected earnings is calculated.','- Skillz old terms link returns a branded 404. Actionable links use the working official homepage, not an invented replacement terms URL.','- AIcrowd extraction contains unrelated spam/HTML-looking categories. No such material was executed or trusted.','- Topcoder extraction contains an Auth0 alert; Zindi current listings are client-rendered placeholders. No prize facts inferred.','- Original date badges are historical. The source header says Pass C / 17 Aug while data reports Pass S / 19 Aug 2026. No freshness claims inherited.','- Source landing page includes a blanket $600 US tax claim. It is not adopted; only contest-specific official tax-document requirements are reproduced.','- 45 historical exclusion records have no official URLs in that exclusion list; preserved separately, unverified, not counted as opportunities.','', '## Line-by-line normalized inventory','', '| Record | Origin | Official field evidence | Blank/unverified fields | Flags |','|---|---|---|---|---|']
    for r in ROWS:
        used=sorted({s for f in r['fields'].values() if f for s in f['sources']})
        links='; '.join('['+SOURCES[s]['title']+']('+SOURCES[s]['url']+')' for s in used)
        if not links:links='No fields verified. [Source candidate]('+r.get('listedOperator',r.get('candidates',[''])[0] if r.get('candidates') else '')+')'
        lines.append('| '+r['name'].replace('|','/')+' | '+r['origin']+' | '+links+' | '+', '.join(r['missing'])+' | '+'; '.join(r['flags']).replace('|','/')+' |')
    lines+=['','## Source notebook','']
    for id,s in SOURCES.items():lines+=['### '+s['title'],s['url'],'Checked 2026-11-01. '+s['notes']]+['> '+q for q in s['excerpts']]+['']
    (ROOT/'research/AUDIT.md').write_text('\n'.join(lines)+'\n')
    # Flat export keeps unknowns genuinely empty. Source IDs and URLs preserve provenance.
    buf=io.StringIO();w=csv.writer(buf);w.writerow(['id','name','category','origin','free_cash_confirmed','source_inspected',*LABELS,'official_evidence_urls','unverified_source_candidates','flags'])
    for r in ROWS:
        used={s for f in r['fields'].values() if f for s in f['sources']}
        w.writerow([r['id'],r['name'],CATS[r['category']],r['origin'],r['freeCash'],r['checked'],*[r['fields'][k]['value'] if r['fields'][k] else '' for k in LABELS],'; '.join(SOURCES[s]['url'] for s in sorted(used)),'; '.join(u for u in r['candidates'] if u not in BAD),'; '.join(r['flags'])])
    (OUT/'data/ledger.csv').write_text(buf.getvalue())

def build():
    OUT.mkdir(exist_ok=True)
    for path in ['assets','data']:
        (OUT/path).mkdir(exist_ok=True)
    for f in (ROOT/'assets').iterdir():shutil.copy(f,OUT/'assets'/f.name)
    shutil.copy(ROOT/'data/ledger.json',OUT/'data/ledger.json')
    (OUT/'research').mkdir(exist_ok=True)
    shutil.copy(ROOT/'research/upstream.json',OUT/'research/upstream.json')
    # Remove an obsolete build-only export, never any repository source.
    (OUT/'data/upstream.json').unlink(missing_ok=True)
    (OUT/'.nojekyll').touch()
    dashboard=heading('The competition research desk','Spend your time on the right challenge.','Find free-to-enter competitions, understand the rules, and make an informed choice.<br>Every confirmed detail has official evidence. Everything else is clearly flagged.',a('./competitions.html','<span>↗</span> Explore all opportunities',**{'class':'button primary'}))
    page('index.html','Overview',dashboard+metrics()+notice()+shortlist()+table(ROWS)+bottom())
    page('competitions.html','All competitions',heading('Explore the ledger','One place. Every opportunity.','Search the full inventory, compare confirmed details, and open the official evidence before you commit.')+notice()+table(ROWS)+bottom())
    page('saved.html','Saved opportunities',heading('Your research shortlist','Keep the opportunities that matter.','Save records with the star button. Your shortlist stays in this browser only; no account or personal information is sent.')+table(ROWS,mode='saved',title='Your saved opportunities'))
    for cat,name in CATS.items():
        desc={'tech':'Coding, data science and research challenges. AI use varies by event; read the exact conditions before building.','forecasting':'Probability forecasts, not wagers. Cash-equivalent substitutions and bot eligibility are highlighted, not hidden.','creative':'Writing, photography and design. Free entry does not imply permission to use generated text or imagery.','directory':'Discovery resources, not prize guarantees. Follow each event’s own official rules before spending time.','pools':'League-management tools are not necessarily funded competitions. No cash prize is assumed for a free tool.'}.get(cat,'A preserved category from the original ledger. Unsupported prize, entry and eligibility claims remain blank.')
        page('categories/'+cat+'.html',name,heading('Category / '+E(name),E(name),desc)+notice('../')+table([r for r in ROWS if r['category']==cat],'../',category=cat,title=E(name)),crumb='Categories')
    summary=heading('Research / Executive briefing','A clearer picture of free cash competitions.','Decision memo · 1 November 2026 · Separate confirmed facts from discovery leads.')+metrics()+f'''<div class="prose"><h2>The executive summary</h2><p>The repository initially contained only a README. The supplied ledger contains 206 listings across nine categories, plus 45 historical exclusions. This dashboard retains all 206 listings and adds 10 event-level records from current official pages. It is a research inventory, not a list of 216 verified free-cash contests.</p><p><strong>{sum(r['freeCash'] for r in ROWS)} records have both free entry and a cash award supported by official evidence.</strong> Three additional Metaculus events have free entry and advertised monetary pools, but official rules permit cash-equivalent payments. They are excluded from the strict free + cash view. Payment method, eligibility and tool permissions remain separate checks.</p><h2>Where to spend research time first</h2><p>These are editorial priorities based on explicit AI/tool rules and concrete deliverables, not a prediction of winning or an estimate of hourly earnings. Fees, compute costs, chances of winning and time-to-complete are not invented.</p><div class="info-card"><h3>1. PayPal AI Hackathon — a focused software build</h3><p>Official rules require a working PayPal sandbox + AI application and say no purchase or payment is necessary. First place is $12,000 USD. Submission period ends 12 November 2026 at 12:00 Pacific Time. A demo and required developer accounts are needed. {source_link('paypal','./','Official rules ↗')}</p><p><strong>Recommended approach:</strong> choose one narrow user problem, validate a sandbox transaction flow, and build an end-to-end demo with a reproducible README. This recommendation is an editorial workflow, not an official scoring guarantee.</p></div><div class="info-card"><h3>2. FutureEval — direct fit for a forecasting bot, with a payout caveat</h3><p>The Fall 2026 event is bot-only, advertises a $50,000 pool and closes 6 January 2027. Official resources say to submit only one forecast per question in the bot-only series. General tournament rules permit cash-equivalent payouts, so withdrawable cash is not guaranteed. {source_link('futureeval','./','Event ↗')} {source_link('bot-resources','./','Bot resources ↗')} {source_link('meta-rules','./','Payment rules ↗')}</p><p><strong>Recommended approach:</strong> first establish a logged baseline, measure calibration, and budget API use. Do not assume free entry means free compute or automated onboarding.</p></div><div class="info-card"><h3>3. NFL Big Data Bowl 2027 — bounded analytics work</h3><p>Rules state no purchase is necessary and list a $100,000 pool across tracks and a final presentation prize. External models and AutoML are conditionally permitted. The deadline is 6 January 2027 at 23:59 UTC; the writeup must link Combine sensor data to NFL performance. {source_link('nfl-rules','./','Rules ↗')} {source_link('nfl-overview','./','Deliverables ↗')}</p><p><strong>Recommended approach:</strong> investigate one position or drill, test a defensible linkage, and show uncertainty rather than claiming a broad scouting solution.</p></div><h2>Important exclusions and restrictions</h2><ul><li>GamerSaloon’s advertised $10 is Bonus Cash and cannot be withdrawn. {source_link('saloon','./','Official promotion ↗')}</li><li>Skillz distinguishes free virtual currency/tickets from deposit-based real-money play. Its inherited terms URL returns a branded 404. {source_link('skillz','./','Working official FAQ ↗')}</li><li>Papaya separates free Gems competitions from cash competitions. No free-to-withdrawable-cash path is confirmed here. {source_link('papaya','./','Official FAQ ↗')}</li><li>Wergle Flomp is free with cash prizes, but prohibits AI-generated text; limited error feedback and disclosure rules apply. {source_link('wergle','./','Contest rules ↗')}</li><li>Sony’s cash awards are in the Series and Single Image tracks. Computer-generated content cannot be the origin of an entry. {source_link('sony-single','./','Single Image rules ↗')} {source_link('sony-series','./','Series rules ↗')}</li><li>ARC has an imminent 2 November submission deadline and 8 November paper deadline; reproducible open-source solutions are required, with no internet/model APIs during Kaggle evaluation. Entry fee is not confirmed in the inspected organizer page. {source_link('arc','./','Organizer rules ↗')}</li><li>GEMS has a $300,000 cash pool and U.S. individual/entity eligibility restrictions. Its explicit entry-fee and AI-assistance policies remain blank in this audit. {source_link('gems','./','Challenge ↗')} {source_link('gems-rules','./','Official PDF ↗')}</li></ul><h2>Audit limitations — visible by design</h2><p>{len(SOURCES)} official pages were inspected. This is not a full line-by-line re-verification of every inherited claim or every external link. Every original row was normalized and checked for required provenance; unsupported operational fields were removed from the comparison dataset and preserved only in the labeled historical archive. Source-page inspection does not mean all chunks, PDFs, legal terms or current account screens were inspected.</p><p>Inherited source candidates not yet checked remain flagged. Twelve source records lack a source explicitly tagged official in the upstream dataset; a signup URL is not proof of authority. Forty-five historical exclusions lack official links in their upstream exclusion records. No unsupported values were promoted to fill gaps.</p><p>{a('./review.html','Flagged for Review →')} &nbsp; {a('./sources.html','Official evidence notebook →')} &nbsp; {a('./data/ledger.csv','Download the normalized inventory →')}</p></div>'''
    page('summary.html','Executive summary',summary)
    reviewintro=heading('Research / Open questions','Flagged for Review','Nothing hidden. Unsupported values stay blank, known issues stay visible, and findings do not block publication.')+f'''<div class="notice review-callout"><span aria-hidden="true">⚐</span><div><strong>Review is a status, not a roadblock.</strong> This page includes every incomplete or caution-bearing record. A source-linked fact can coexist with unverified payout or eligibility details. This publication does not claim the entire inventory is verified.</div></div><div class="bottom-grid"><section class="info-card"><h2>Known broken link · Skillz</h2><p><code>https://www.skillz.com/terms-of-service/</code> returns an official branded 404. It is removed from actionable source links; no replacement terms URL is guessed.</p>{a('https://www.skillz.com/','Working official homepage ↗')}</section><section class="info-card"><h2>Extraction and evidence gaps</h2><p>AIcrowd returned noisy/spam categories. Topcoder displayed an Auth0 alert. Zindi’s counts were placeholders. These are extraction limitations, not evidence the platforms have closed.</p>{a('./sources.html','See inspection notes ↗')}</section></div>'''
    historical='<section class="historical"><h2>Historical exclusions · 45 archived names</h2><p class="lede">These are not active opportunities and are not independently verified. The upstream exclusion records supply names and reasons, but no official URLs. No official links or current statuses have been invented.</p><p>'+a(UPSTREAM,'Review upstream exclusion record ↗')+'</p><details><summary>Show the archived exclusion names and upstream reasons</summary><ul>'+''.join('<li><strong>'+E(x['name'])+'</strong> — '+E(x['why'])+' (unverified)</li>' for x in D['historicalExclusions'])+'</ul></details></section>'
    page('review.html','Flagged for Review',reviewintro+table([r for r in ROWS if r['flags']],mode='review',title='Flagged records & incomplete evidence')+historical)
    method=heading('Research / The standard','Evidence first. Always.','What a sourced field means, what it does not mean, and how to reproduce this publication.')+'''<div class="prose"><h2>Our verification contract</h2><ol><li><strong>Official sources only for facts.</strong> Prize, fee, deadline, eligibility, AI rules, payment and deliverables must cite the organizer, official rules or designated hosting platform. The legacy ledger is provenance, not verification.</li><li><strong>Unknown means empty.</strong> Unconfirmed values are null in JSON, empty in CSV and blank in the table. Review reasons say what remains unverified. No estimated cashout limits, dates, probabilities or earnings.</li><li><strong>Field-level, not blanket, evidence.</strong> Each populated field links directly to its supporting official source. “Source inspected” describes an observation, not a certification of every claim or personal eligibility.</li><li><strong>Free + cash filter.</strong> An explicit free-entry statement plus a cash award must be sourced. Cash-equivalent substitutions, bonus balances and equipment-only prizes are excluded from this strict view. A positive result is still not a payout or eligibility guarantee.</li><li><strong>AI rules are not interchangeable.</strong> Human assistance, AutoML, bot participation and generated creative work are different permissions. A conditional allowance is not permission for all automation. Missing AI rules stay blank.</li><li><strong>Deadlines are exact where available.</strong> Source date/time wording is retained. Unknown timezones and years are not inferred. A sort date is used only where a full calendar date was explicitly available. Availability is a dated snapshot, not a real-time feed.</li><li><strong>No double-counting.</strong> Platform and event entries may overlap, as do headline pools and track awards. There is no aggregate prize total. A pool is not an individual winner’s award.</li></ol><h2>How to use the dashboard</h2><p>Use the Free + cash sourced tab for the strict shortlist, select an evidence or AI filter, and expand Details &amp; verification for eligibility, payment, deliverables and flags. Empty cells are intentional. Saved records live only in this browser’s local storage. CSV exports contain the full normalized inventory, not just the current filtered page.</p><h2>Coverage and link checks</h2><p>The build validates every normalized row, evidence reference, source URL format, category, date, internal link and published asset. Browser tests exercise mobile layouts, filtering, pagination, saved records and accessibility. Unchecked inherited external links may still be broken. These checks do not prove every external website is reachable or every legacy claim is correct. The official-source notebook describes exactly which pages/chunks were inspected. Unchecked external links are visibly labeled source candidates. Known broken links are retained as text in findings, not as actionable source links.</p><h2>Reproduce or update</h2><p>Run <code>npm run build</code> and <code>npm test</code>. The site is generated without third-party build dependencies. Curated fields and source excerpts are in <code>data/findings.json</code>; the untouched historical claim archive is in <code>research/upstream.json</code>. The generator produces category subpages, a full JSON/CSV export and a line-by-line audit. Editing imported historical claims does not verify them.</p><h2>Independence and safety</h2><p>No affiliate links, sponsors, signups, analytics, payment collection or contest entries are made by this site. No tax threshold or legal eligibility is inferred. Consult the official rules before registering, uploading confidential work or spending on tools. Prize values, rules and availability can change after this snapshot.</p></div>'''
    page('methodology.html','Verification method',method)
    sourcehtml=heading('Research / Official evidence','The source notebook','Thirty-one official pages inspected on 1 November 2026. Excerpts support specific fields, not an entire platform. Partial inspections are disclosed.')+'<div class="prose"><div class="notice">These are inspection notes and short supporting excerpts, not full legal documents or live uptime checks. Source candidates for the remaining inherited rows are unverified and appear in each row’s details.</div>'
    for id,s in SOURCES.items():
        sourcehtml+=f'<section class="source-record" id="{id}"><h2>{E(s["title"])}</h2>{a(s["url"],E(s["url"]))}<p>Inspected: {s["checked"]} · {E(s["result"])}</p>'+''.join('<blockquote>'+E(q)+'</blockquote>' for q in s['excerpts'])+('<p><strong>Scope / cautions:</strong> '+E(s['notes'])+'</p>' if s['notes'] else '')+'</section>'
    page('sources.html','Source notebook',sourcehtml+'</div>')
    page('404.html','Page not found',heading('404 / Not found','This page is not in the ledger.','The link may be out of date. Return to the dashboard or browse the full inventory.',a('./index.html','Back to overview',**{'class':'button primary'})))
    audit_files()
    if '--publish-root' in sys.argv:
        # Existing Pages configuration is main:/ and its settings API is not writable.
        # Commit only the exact static pages/exports required by that publishing route.
        for generated in list(OUT.rglob('*.html'))+[OUT/'.nojekyll',OUT/'data/ledger.csv']:
            target=ROOT/generated.relative_to(OUT)
            target.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy(generated,target)
    print(f'Built {len(list(OUT.rglob("*.html")))} pages · {len(ROWS)} records · {len(SOURCES)} official sources · {sum(r["freeCash"] for r in ROWS)} free + cash sourced')
if __name__=='__main__':build()
